function buildPivotSummaryInWorker(spec:PivotSummarySpec,destinationId=doc.activeId,requireActiveDestination=true,requireUnchangedSavedSpec=false,detailRef?:string):Promise<PivotSummaryResult>{
 const requestId=`pivot-${++pivotWorkerSequence}`,snapshot=doc.toJSON(),revisions=doc.sheets.map(sheet=>({id:sheet.id,name:sheet.name,revision:sheet.book.valueRevision})),destination=doc.sheets.find(sheet=>sheet.id===destinationId),specSnapshot=JSON.stringify(spec);
 if(!destination)return Promise.reject(new Error('The PivotTable destination worksheet no longer exists.'));
 if(typeof Worker==='undefined'){
  const sourceName=spec.sourceSheet??destination.name,source=doc.sheets.find(sheet=>sheet.name.toLocaleLowerCase()===sourceName.toLocaleLowerCase());
  if(!source)return Promise.reject(new Error(`Pivot source worksheet “${sourceName}” is unavailable.`));
  return Promise.resolve(buildPivotSummary(destination.book,spec,source.book,detailRef));
 }
 return new Promise((resolve,reject)=>{
  let worker:Worker;
  try{worker=new Worker(new URL('./engine/pivot_worker.js',import.meta.url),{type:'module'});}catch(error){reject(error instanceof Error?error:new Error('Unable to start PivotTable calculation.'));return;}
  const finish=(callback:()=>void)=>{worker.terminate();callback();};
  worker.onmessage=(event:MessageEvent<PivotJobResponse>)=>finish(()=>{
   const response=event.data;
   if(response.requestId!==requestId){reject(new Error('PivotTable calculation returned an unexpected response.'));return;}
   if(response.error){reject(new Error(response.error));return;}
   const currentSpec=requireUnchangedSavedSpec?doc.sheets.find(sheet=>sheet.id===destinationId)?.tools.pivotTables.find(item=>item.id===spec.id):spec;
   if((requireActiveDestination&&doc.activeId!==destinationId)||!doc.sheets.some(sheet=>sheet.id===destinationId)||doc.sheets.length!==revisions.length||doc.sheets.some((sheet,index)=>sheet.id!==revisions[index]?.id||sheet.name!==revisions[index]?.name||sheet.book.valueRevision!==revisions[index]?.revision)||(requireUnchangedSavedSpec&&(!currentSpec||JSON.stringify(currentSpec)!==specSnapshot))){reject(new Error('Workbook data changed while the PivotTable was being calculated. Retry to use the latest values.'));return;}
   if(response.result)resolve(response.result);else reject(new Error('PivotTable calculation returned no result.'));
  });
  worker.onerror=()=>finish(()=>reject(new Error('PivotTable calculation stopped unexpectedly.')));
  try{worker.postMessage({requestId,document:snapshot,destinationSheetId:destinationId,spec,...(detailRef?{detailRef}:{})} satisfies PivotJobRequest);}catch(error){finish(()=>reject(error instanceof Error?error:new Error('Unable to send workbook data to the PivotTable calculator.')));}
 });
}
function buildPivotSummariesInWorker(specs:PivotSummarySpec[],destinationId:string):Promise<PivotBatchJobResponse['results']>{
 const requestId=`pivot-batch-${++pivotWorkerSequence}`,snapshot=doc.toJSON(),revisions=doc.sheets.map(sheet=>({id:sheet.id,name:sheet.name,revision:sheet.book.valueRevision})),specSnapshots=specs.map(spec=>JSON.stringify(spec)),destination=doc.sheets.find(sheet=>sheet.id===destinationId);
 if(!destination)return Promise.reject(new Error('The PivotTable destination worksheet no longer exists.'));
 if(typeof Worker==='undefined'){
  const response=runPivotJobs({requestId,document:snapshot,destinationSheetId:destinationId,specs});return response.error?Promise.reject(new Error(response.error)):Promise.resolve(response.results);
 }
 return new Promise((resolve,reject)=>{
  let worker:Worker;
  try{worker=new Worker(new URL('./engine/pivot_worker.js',import.meta.url),{type:'module'});}catch(error){reject(error instanceof Error?error:new Error('Unable to start PivotTable calculation.'));return;}
  const finish=(callback:()=>void)=>{worker.terminate();callback();};
  worker.onmessage=(event:MessageEvent<PivotBatchJobResponse>)=>finish(()=>{
   const response=event.data;
   if(response.requestId!==requestId){reject(new Error('PivotTable batch calculation returned an unexpected response.'));return;}
   if(response.error){reject(new Error(response.error));return;}
   const currentDestination=doc.sheets.find(sheet=>sheet.id===destinationId),changed=doc.sheets.length!==revisions.length||doc.sheets.some((sheet,index)=>sheet.id!==revisions[index]?.id||sheet.name!==revisions[index]?.name||sheet.book.valueRevision!==revisions[index]?.revision)||specs.some((spec,index)=>JSON.stringify(currentDestination?.tools.pivotTables.find(item=>item.id===spec.id))!==specSnapshots[index]);
   if(changed){reject(new Error('Workbook data changed while the PivotTables were being calculated. Retry to use the latest values.'));return;}
   resolve(response.results);
  });
  worker.onerror=()=>finish(()=>reject(new Error('PivotTable batch calculation stopped unexpectedly.')));
  try{worker.postMessage({requestId,document:snapshot,destinationSheetId:destinationId,specs} satisfies PivotBatchJobRequest);}catch(error){finish(()=>reject(error instanceof Error?error:new Error('Unable to send workbook data to the PivotTable calculator.')));}
 });
}
