function suggestedChartRange():string {
 const b=sel();if(b.r1!==b.r2||b.c1!==b.c2)return `${asRef(b.r1,b.c1)}:${asRef(b.r2,b.c2)}`;
 const existing=tableAt(doc.active.tools.tables,active.r,active.c,book.rows,book.cols);if(existing)return existing.range;
 if(book.getRaw('A3')==='SKU'&&active.r<=14)return 'A3:D11';
 const c1=Math.max(0,active.c-1),c2=Math.min(book.cols-1,active.c+1),r1=Math.max(0,active.r-1);
 let last=r1;for(let r=r1;r<Math.min(book.rows,r1+30);r++){if(r>r1&&!Array.from({length:c2-c1+1},(_,i)=>book.getRaw(asRef(r,c1+i))).some(Boolean))break;last=r;}
 return `${asRef(r1,c1)}:${asRef(Math.max(r1+1,last),c2)}`;
}
function parseWaterfallTotalPointInput(input:string,pointCount:number):number[]{
 const tokens=input.split(',').map(value=>value.trim()).filter(Boolean);
 if(tokens.some(value=>!/^[1-9]\d*$/.test(value)))throw Error('Enter Waterfall item positions as positive whole numbers separated by commas.');
 const oneBased=[...new Set(tokens.map(Number))].sort((a,b)=>a-b);
 if(oneBased.some(value=>value>pointCount))throw Error(`Waterfall total item indexes must be between 1 and ${pointCount}.`);
 return oneBased.map(value=>value-1);
}
