interface GridForgeDesktopAPI { save_file: (filename:string,mime:string,dataBase64:string)=>Promise<string> }
const desktopAPI=():GridForgeDesktopAPI|null => {
  const bridge=window as Window & {pywebview?:{api?:GridForgeDesktopAPI}};
  return bridge.pywebview?.api?.save_file ? bridge.pywebview.api : null;
};
function download(name:string,contents:string|Uint8Array,type:string){
  const native=desktopAPI();
  if(native){
    const bytes=typeof contents==='string'?new TextEncoder().encode(contents):contents;
    let encoded='';
    for(let i=0;i<bytes.length;i+=8192) encoded+=String.fromCharCode(...bytes.subarray(i,i+8192));
    void native.save_file(name,type,btoa(encoded)).then(status=>{
      if(status==='saved')toast('Saved using the Windows file dialog.');
      else if(status!=='cancelled')toast('Save did not complete.');
    }).catch(error=>toast(`Save failed: ${error instanceof Error?error.message:String(error)}`));
    return;
  }
  const url=URL.createObjectURL(new Blob([typeof contents==='string'?contents:new Uint8Array(contents)],{type}));
  const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);
}
